    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- The people a person names as their patrons: each pair once, and never a person as their own patron.
CREATE TABLE patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CONSTRAINT patron_not_self CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX patron_pair ON patron (person_id, patron_id);
CREATE INDEX patron_sheet ON patron (sheet_id, id);
-- A rate can carry a from-date: a grade may have several rates, each in force from its from-date
-- until the next one's. A rate with no from-date applies from the beginning of time. A grade has at
-- most one rate per from-date (and at most one with none).
CREATE TABLE rate_dated (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade     VARCHAR(1)   NOT NULL,
    from_date DATE,
    rate      DECIMAL(5, 2) NOT NULL CHECK (rate >= 0),
    CONSTRAINT rate_sheet_grade_from UNIQUE NULLS NOT DISTINCT (sheet_id, grade, from_date)
);
