test("grade dated scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.25", "date": "2026-03-01"}));
  const c_ada_1 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ada", "amount": "0.04"}, p_ada));
  await ui.setToday(pg_uma, "2026-04-08");
  expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33", "from": "2026-03-01"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ada, {"grade": "C"})).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("10.25");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("10.25");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  expect(await ui.editClaim(pg_uma, c_ada_1, {"amount": "20.00"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
  const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
  expect(await ui.retire(pg_uma, p_ada, "2026-03-28")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.editPerson(pg_uma, p_ada, {"grade": "A"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ada_2, "open")).toBe(true);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("50.25");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("9.17");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-due")).toHaveText("6.67");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-stated")).toHaveText("yes");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("2.50");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-stated")).toHaveText("yes");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("yes");
